function moveZeroes(nums) {
  let temp = [];
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] !== 0) temp.push(nums[i]);
  }
  while (temp.length < nums.length) {
    temp.push(0);
  }
  for (let i = 0; i < nums.length; i++) {
    nums[i] = temp[i];
  }
  return nums;
}

